duct_cat\",\"id\":24,\"url\":\"http://localhost/BanDoChoi/be-trai/\",\"kind\":\"taxonomy\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/term-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Bé gái\",\"type\":\"product_cat\",\"id\":25,\"url\":\"http://localhost/BanDoChoi/be-gai/\",\"kind\":\"taxonomy\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/term-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-submenu {\"label\":\"THEO ĐỘ TUỔI\",\"type\":\"page\",\"id\":42,\"url\":\"http://localhost/BanDoChoi/theo-do-tuoi/\",\"kind\":\"post-type\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/post-data\",\"args\":{\"field\":\"link\"}}}}} -->\n<!-- wp:navigation-link {\"label\":\"0-12 Tháng\",\"type\":\"product_cat\",\"id\":27,\"url\":\"http://localhost/BanDoChoi/0-12-thang/\",\"kind\":\"taxonomy\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/term-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"1-3 Tuổi\",\"type\":\"product_cat\",\"id\":28,\"url\":\"http://localhost/BanDoChoi/1-3-tuoi/\",\"kind\":\"taxonomy\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/term-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"3-6 Tuổi\",\"type\":\"product_cat\",\"id\":29,\"url\":\"http://localhost/BanDoChoi/3-6-tuoi/\",\"kind\":\"taxonomy\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/term-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n\n<!-- wp:navigation-link {\"label\":\"Trên 6 tuổi\",\"type\":\"product_cat\",\"id\":30,\"url\":\"http://localhost/BanDoChoi/tren-6-tuoi/\",\"kind\":\"taxonomy\",\"metadata\":{\"bindings\":{\"url\":{\"source\":\"core/term-data\",\"args\":{\"field\":\"link\"}}}}} /-->\n<!-- /wp:navigation-submenu -->\n\n<!-- wp:navigation-link {\"label\":\"KHUYẾN MÃI\",\"type\":\"page\",\"id\":11,\"url\":\"http://localhost/BanDoChoi/khuyen-mai/\",\"kind\":\"post-type\",\"metadata\":{\"bindings\":{\